[200023] = {id = 200023, name = "一種遺憾", icon = "Icon_Event_Ticket3", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "參與海因的寫生所需要的特殊道具。預知一次未來，收穫一種遺憾。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200024] = {id = 200024, name = "虹色晶塊", icon = "Icon_Event_Coin7", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "暗紅的水晶塊，從不同的角度能看到不同顏色的光芒。就像一個囚籠，將色彩禁錮在那血一般的黏稠之中。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200025] = {id = 200025, name = "宅急送優惠券", icon = "Icon_Event_Coin8", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "“飛速食品”為了響應購物節而製作的優惠券，老闆以不便出鏡為由強行徵用了赫莉的形象。注意：本優惠券不能與其他優惠疊加使用。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200026] = {id = 200026, name = "星之遺物", icon = "Icon_Event_Ticket4", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "聽說是准罪級原罪埃柏爾身上最珍貴的部件，在科研部受到追捧。那些殺不死我們的，只會使我們更加強大。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200027] = {id = 200027, name = "絕望要素", icon = "Icon_Event_Crystal1", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "被冠以“絕望”之名的實驗型尼姆比斯晶體。是身處絕望之人最後的救命稻草，也是賦予最後絕望的鑰匙。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200028] = {id = 200028, name = "“魔材料”可哥之豆", icon = "Icon_Event_Coin9", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "能製作“魔道具”巧克力的稀世材料。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200029] = {id = 200029, name = "聖水滴", icon = "Icon_Event_Coin10", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "至純的聖水滴，取自珀因雷德最高峰的泉源，據說蘊含著神奇的力量，即使將其長久靜置也能如流水不腐。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200030] = {id = 200030, name = "一日特訓券", icon = "Icon_Event_Ticket5", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "允許動用戰略資源進行幻化訓練的特訓券。曾有懶惰的駕駛員與愛玩遊戲的駕駛員私下對該券進行過交易，現在則已明令禁止。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200031] = {id = 200031, name = "色彩的含義", icon = "Icon_Event_Coin11", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "參與海因的寫生所需要的特殊道具。紙上的線條與色彩是海因的言語——這是屬於她的表達方式。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200032] = {id = 200032, name = "蘿蔔密鑰", icon = "Icon_Event_Coin12", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "蕩漾兔結合自己的駭客知識製作的網絡貨幣，幾乎可以在任何購物網站上使用。顯然，這是違法的，但對於身為壞孩子的她來說，這是一種樂趣。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200033] = {id = 200033, name = "宇宙POINT", icon = "Icon_Event_Coin13", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "女主角宇宙的流通貨幣，每月會有低保的額度發放到“宇宙通行證”中。如果想要在宇宙中享樂，僅憑低保的這點數額還遠遠不夠，想要賺取point就要去女主角協會接取任務。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200034] = {id = 200034, name = "宇宙和平星", icon = "Icon_Event_Ticket7", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "只有被女主角宇宙認可的人才能擁有的“宇宙和平星”，持有它的人能成為掌握宇宙規則的【星之君主】。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200035] = {id = 200035, name = "星之手劄", icon = "Icon_Event_Ticket6", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "斯卡蒂會在零散的書頁上記錄偶然的靈感。因為靈感來得突然，所以她經常隨寫隨放，導致在事後會忘記把書頁放在什麼地方。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200036] = {id = 200036, name = "入睡枕", icon = "Icon_Event_Coin14", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "想要做一個好夢的話，就得有一個能讓你舒舒服服把腦袋放上去的枕頭——當然，也得注意不要落枕。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200037] = {id = 200037, name = "謎之藍光碟", icon = "Icon_Event_Ticket8", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "電影鑒賞大會最讓人期待的地方就是，你永遠猜不到下一部電影是爛片還是好片。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200038] = {id = 200038, name = "副音軌？", icon = "Icon_Event_Ticket9", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "「千呼萬喚始出來，由阿爾泰婭·維斯投入100%心血與100%興趣主持的節目，《美夢不再》副音軌正式上映！」", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200039] = {id = 200039, name = "聖誕拐杖糖", icon = "Icon_Event_Coin15", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "在耶誕節期間隨處可見的拐杖糖，用白砂糖和玉米糖漿混合製作的廉價甜蜜，是完美身材的“毒藥”。聽說有人正在收集它們，甚至不惜拿出一些珍貴物品交換。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200040] = {id = 200040, name = "姜餅人兄妹", icon = "Icon_Event_Ticket10", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "「赫洛卡」特製的釣魚餌料，兩個手牽在一起的薑餅人，看著像是一對形影不離的兄妹。薑餅人散發著濃鬱的奇妙香氣，對於水下的魚兒來說也是難得的珍饈。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[200041] = {id = 200041, name = "魚罐頭", icon = "Icon_Event_Ticket11", quality = 3, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "從魚肚子裏找到的還未開封的罐頭，雖然密封性很好但是裹滿了魚腥味。不知來源的罐頭勾引起了你的好奇心，只希望打開後不會聽到尷尬的笑聲。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
