[400000] = {id = 400000, name = "查麗莎的日記「一」", icon = "icon_rijiben_cls_1", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上撰寫著查理斯不為人知的情報。\n那是查麗莎的噩夢，被她盡數藏進了衣櫃中。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400001] = {id = 400001, name = "查麗莎的日記「二」", icon = "icon_rijiben_cls_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上撰寫著查理斯不為人知的情報。\n直到你冒冒失失地打開了衣櫃。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400002] = {id = 400002, name = "查麗莎的日記「三」", icon = "icon_rijiben_cls_3", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上撰寫著查理斯不為人知的情報。\n並沒有曲折的故事，僅僅只是一起去買衣服罷了。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400003] = {id = 400003, name = "查麗莎的日記「四」", icon = "icon_rijiben_cls_4", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上撰寫著查理斯不為人知的情報。\n但是由心鬱結而成壁，已經悄然裂開。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400004] = {id = 400004, name = "查麗莎的日記「五」", icon = "icon_rijiben_cls_5", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上撰寫著查理斯不為人知的情報。\n對你的思念超過了對噩夢的恐懼，於是查麗莎向前進發。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400005] = {id = 400005, name = "查麗莎的更衣室手牌", icon = "icon_czticket_chalisha", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "「今天與您通感的，是那名離家出走的大小姐查麗莎。\n她正在等著您，快去吧。」", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400100] = {id = 400100, name = "多洛莉絲的日記「一」", icon = "icon_rijiben_dlls_1", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上收錄著多洛莉絲最近的一舉一動和每一份體檢報告。\n履行完自己的責任後，多洛莉絲重新把視線投到自己的身上。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400101] = {id = 400101, name = "多洛莉絲的日記「二」", icon = "icon_rijiben_dlls_2", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上收錄著多洛莉絲最近的一舉一動和每一份體檢報告。\n多洛莉絲是凡人，背負著已逝之人的愛前行的凡人。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400102] = {id = 400102, name = "多洛莉絲的日記「三」", icon = "icon_rijiben_dlls_3", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上收錄著多洛莉絲最近的一舉一動和每一份體檢報告。\n無論是過去，抑或者現在，還是不久的將來，凡人們都在不斷蒙受別人的好意前進。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[400103] = {id = 400103, name = "多洛莉絲的日記「四」", icon = "icon_rijiben_dlls_4", quality = 4, use = 0, fall = "0", superposition = 1, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "與調度書上的檔案不同，這份只為你開啟的秘密資料上收錄著多洛莉絲最近的一舉一動和每一份體檢報告。\n但好在，於這場種族存續之戰中，無論是凡人還是天才，都只能反復把自己押入槍膛。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
