[920009] = {id = 920009, name = "億千萬的點滴", icon = "icon_huizhang_cfduoluolisi_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "你的每一句話語，都成為了少女心中的勇氣。", group = 0, itemstar = 0, describe = "达成成就：億千萬的點滴", costeffect = "0", appear = 2, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
