[920011] = {id = 920011, name = "進修中的惡魔新娘", icon = "icon_huizhang_fulankaxiaoemo_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "對於少女來說，稚嫩或許是褒義，但對於弗蘭卡來說，她需要的是成熟。", group = 0, itemstar = 0, describe = "达成成就：進修中的惡魔新娘", costeffect = "0", appear = 2, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
