[920013] = {id = 920013, name = "魔女之卵", icon = "icon_huizhang_sikadimonv_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "這是久遠到被遺忘的故事，就連斯卡蔕自己都忘記了。我們還會再見面吧？", group = 0, itemstar = 0, describe = "达成成就：魔女之卵", costeffect = "0", appear = 2, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[920014] = {id = 920014, name = "慶賀吧！最強的魔女誕生了！", icon = "icon_huizhang_sikadimonv_02", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "吾乃開辟宇宙的第一曙光，被冠以“魔女”之名的星之君主。我們一定會再見面的！", group = 0, itemstar = 0, describe = "達成成就：慶賀吧！最強的魔女誕生了！", costeffect = "0", appear = 2, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
