[60000006] = {id = 60000006, name = "遺落的相紙", icon = "icon_yure_xiansuo", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "不知是誰遺落的照片相紙，只要甩一甩就能看到拍攝的內容。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001001] = {id = 60001001, name = "好久不見", icon = "Img_yure_xiansuo_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "絕望的呼聲自十二年前迴響至今，如今她重返故土，想著這一次會有一個不一樣的結局。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001002] = {id = 60001002, name = "並不是修羅場", icon = "Img_yure_xiansuo_02", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "這是一次不在計畫內的相遇，但是並不壞——至少被幸運眷顧的少女對此相當滿意。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001003] = {id = 60001003, name = "不要玩弄朋友", icon = "Img_yure_xiansuo_03", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "比起人類，還是小動物更加討她的喜歡——畢竟它們很少撒謊。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001004] = {id = 60001004, name = "例行巡邏", icon = "Img_yure_xiansuo_04", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "這是少女生活的街道，儘管自己的能力微不足道，但她決定用特別的方式去守護它。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001005] = {id = 60001005, name = "姐妹情深……", icon = "Img_yure_xiansuo_05", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "就算拔光毛髮，揪斷尾巴，咬破皮肉，她也要把自己的妹妹從它的體內帶出來。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60001006] = {id = 60001006, name = "約會？這不重要", icon = "Img_yure_xiansuo_06", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "已經多久沒有享受這種純粹的快樂了，她記不得了。享受當下才是重中之重。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002001] = {id = 60002001, name = "甜莓果醬多瑙皇家布丁", icon = "Img_CookBook_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "為布丁取了看起來很厲害的名字，價格是普通布丁的三十倍。千秋給出的分數是3分，考慮到價格把分數也降了三十倍。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002002] = {id = 60002002, name = "薩哈拉黑豬排三明治", icon = "Img_CookBook_02", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "沒想到在卡佳也能吃到地道的薩哈拉美食。用的是合成肉。千秋給出的分數是60分，因為是肉。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002003] = {id = 60002003, name = "紅椒碎醬爆鐵板豆腐", icon = "Img_CookBook_03", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "聞臭吃香，外焦微脆，內軟味鮮。千秋給出的分數是81分，頗有嚼頭。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002004] = {id = 60002004, name = "洛根穀飼牛肉餡餅", icon = "Img_CookBook_04", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "名偵探千秋又因為想要品嘗美食被迫破獲了一場兇殺案。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002005] = {id = 60002005, name = "豚骨背脂叉燒溏心蛋太郎拉麵", icon = "Img_CookBook_05", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "傳聞原罪動亂的時候，入侵的原罪停在了這份剛做好的拉麵前，為了不破壞這份美好，原罪主動退去。千秋給出的分數是90分，不正宗。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002006] = {id = 60002006, name = "酥炸脆薯卡佳鱈", icon = "Img_CookBook_06", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "傳聞中每一任卡佳方舟的支部長都會來品嘗這道美食，驚為天人，留下了感動的淚水。千秋給出的分數是50分。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60002007] = {id = 60002007, name = "什錦水果三色霜淇淋漢堡", icon = "Img_CookBook_07", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "在所有“霜淇淋漢堡”中千秋最喜歡吃的一款。千秋給出的分數是滿分100分。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003001] = {id = 60003001, name = "低筋麵粉", icon = "Img_foodmat_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "使用高筋麵粉和玉米澱粉1：1比例調和而成。加入適度打發的蛋液，揉搓成麵團。可以製作出鬆軟可口的蛋糕胚子。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003002] = {id = 60003002, name = "淡奶油", icon = "Img_foodmat_02", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "脂肪含量在35-38%的動物性奶油，口感順滑，奶香濃郁，一般高檔蛋糕店才會使用。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003003] = {id = 60003003, name = "什錦盒子", icon = "Img_foodmat_03", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "裝滿了各種食材的盒子，可以用於蛋糕的裝飾。能獲得什麼完全看運氣，甚至有可能是空盒。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003004] = {id = 60003004, name = "繽紛夏日蛋糕", icon = "Img_cake_01", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "草莓，鳳梨，奇異果……五彩繽紛的水果擠滿了美味的蛋糕，令人一年四季都能感受到夏天的氣息。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003005] = {id = 60003005, name = "巧克力玫瑰蛋糕", icon = "Img_cake_02", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "90%的巧克力濃漿澆蓋110%的鬆軟胚子，得到的是200%的美味。請細心品嘗，巧克力玫瑰將在你的味蕾上綻放。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003006] = {id = 60003006, name = "純白天使蛋糕", icon = "Img_cake_03", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "純潔如雪，純淨如霜。無需多餘的點綴，你本身就已是完美。就像是從天堂降臨的天使，秉持上帝的旨意，賜福我的舌尖。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[60003007] = {id = 60003007, name = "史蒂芬妮籌碼", icon = "Img_foodmat_04", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "以史蒂芬妮的形象為原型的籌碼。在駕駛員中秘密流通，聽說持有籌碼的駕駛員可以登上淩晨2點的豪華遊輪賭場。", group = 0, itemstar = 0, describe = "0", costeffect = "0", appear = 0, anime = "0", numlimt = -1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
