[98000020] = {id = 98000020, name = "黃金角鬥士·射手", icon = "Img_Touxiang_master12", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第12賽季入圍選手獲得的榮耀，閃耀的星矢承載著你的樂觀與冒險精神。\n“無論前路多少險阻，你總會將疾速的一箭射出，帶著你的好奇心探索那未知的前路風景。”", group = 0, itemstar = 0, describe = "大師賽", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98000021] = {id = 98000021, name = "蛋糕與慶典", icon = "Img_Touxiang_2026zhounian", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "雖然不是生日，但是也可以喫蛋糕。", group = 0, itemstar = 0, describe = "大师赛", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98001001] = {id = 98001001, name = "最後的王牌", icon = "Img_Touxiang_master13", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第13賽季入圍選手獲得的榮耀，授予在關鍵時刻一錘定音的決勝者，你掌上的皇後是你最後的王牌。\n“當戰局被黑暗籠罩，你將收執王牌，成爲貫穿棋盤的那道裁決之光。”", group = 0, itemstar = 0, describe = "大師賽", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98001002] = {id = 98001002, name = "於幻中霹靂", icon = "Img_Touxiang_master14", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第14賽季入圍選手獲得的榮耀，授予能勘破一切表象與戰術迷霧的指揮官。\n“當對手仍沉溺於編織復雜的幻象，你眼中已映出其唯一的破綻——並以一道霹靂，將其徹底貫穿。”", group = 0, itemstar = 0, describe = "大師賽", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98001003] = {id = 98001003, name = "一瞬煙火", icon = "Img_Touxiang_master15", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第15賽季入圍選手獲得的榮耀，綻放的煙花是在慶賀你立下的功績。\n“於夜幕上綻放的煙花，讓時間的流逝也變得緩慢，你眼中映出的景象，正是勝利為你帶來的豐收。”", group = 0, itemstar = 0, describe = "大師賽", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98001004] = {id = 98001004, name = "最後防線", icon = "Img_Touxiang_master16", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第16賽季入圍選手獲得的榮耀，由你鑄成的防線將改寫戰局。\n“防守並不是一昧地挨打，而是為了真正的反擊而積蓄力量。”", group = 0, itemstar = 0, describe = "大師賽", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
[98001005] = {id = 98001005, name = "“無限”", icon = "Img_Touxiang_master17", quality = 4, use = 0, fall = "0", superposition = 0, limit = "0", delete = "0", checkpoint = "0", channel = "0", txt = "大師賽第17賽季入圍選手獲得的榮耀，授予在有限的時間中追求無限之意義的攀登者。\n“以有限去挑戰無限，看似愚蠢的背後藏着比肩神明的勇氣。”", group = 0, itemstar = 0, describe = "大师赛", costeffect = "0", appear = 0, anime = "0", numlimt = 1, timelimt = "0", skintype = 0, "0", "0", "0", "0"},
